public class Ex06 {
    static class Counter { int n; }
    static class SingletonFactory {
        private final Counter single = new Counter(); // 只建一次
        Counter get() { return single; }
    }
    static class PrototypeFactory {
        Counter get() { return new Counter(); } // 每次新建
    }
    public static void main(String[] args) {
        SingletonFactory sf = new SingletonFactory();
        Counter a = sf.get(); Counter b = sf.get();
        a.n = 10;
        System.out.println("singleton same instance? " + (a == b));
        System.out.println("singleton shared state: " + b.n);

        PrototypeFactory pf = new PrototypeFactory();
        Counter c = pf.get(); Counter d = pf.get();
        c.n = 5;
        System.out.println("prototype same instance? " + (c == d));
        System.out.println("prototype independent state: " + d.n);
    }
}
